UPDATE account_roles SET permissions=permissions || '{"system.processing_view":"all","references.download":"all"}'::jsonb
WHERE id='employee' AND permissions->>'photos.create'='all' AND NOT EXISTS(SELECT 1 FROM users WHERE role_id='employee');
