UPDATE account_roles SET permissions=permissions || '{"photos.view":"all","photos.create":"all","photos.upload":"all","photos.rename":"all","photos.media":"all","photos.download":"all","photos.delete_file":"all","photos.delete":"all","photos.process":"all","photos.reprocess":"all","photos.auto":"all","photos.retention":"all","photos.prepare":"all","references.view":"all","references.download":"all","references.export":"all","references.import":"all","references.create":"all","references.edit":"all","references.sides":"all","references.delete_file":"all","references.delete":"all","references.region":"all","queue.view":"all","queue.detail":"all","queue.stop":"all","queue.shared":"all","queue.preparation":"all","logs.view":"all","accounts.view":"all","accounts.storage":"all","accounts.requests":"all","accounts.roles":"all","accounts.create":"all","accounts.approve":"all","accounts.edit":"all","accounts.assign":"all","accounts.overrides":"all","accounts.block":"all","accounts.password":"all","accounts.sessions":"all","accounts.revoke":"all","accounts.quota":"all","accounts.grants":"all","accounts.history":"all","system.models":"all","system.processing_view":"all"}'::jsonb
